'use strict';
// The divergences from node that the differential TOLERATES today: EXACT (case id, field) pairs, in
// known-divergences.json, each under one cause, each cause named in BACKLOG.md under BACKLOG_HEADING.
//
// A field of a case diverging from node is tolerated only when that very pair is listed for this
// platform; any other field of the same case, or the same field of another case, fails the gate. A
// listed pair that no longer diverges fails it too, so the list only shrinks in the commit that fixes
// something (or is regenerated by test/shim-differential/freeze.cjs from a measured run, which is a
// reviewed diff of this data). Until 2026-11-19 a cause was a pattern over APIs, and eight patterns
// named no field: 276 of 1785 cases were tolerated whatever they answered (review finding, fix
// round 1). The patterns below now only CLASSIFY a measured pair when the list is regenerated; they
// tolerate nothing themselves, and freeze.cjs refuses a pair no pattern claims.
const BACKLOG_HEADING = 'node-shim against node: what the behaviour differential names (2026-11-19)';
const KNOWN = require('./known-divergences.json');

const ERR = '^r\\.error\\.(ctor|name|message|code|errno|syscall|path|dest)$';
const CAUSES = [
  // r.closed: the shim's open throws before there is a stream, so there is no .closed to report (node's stream
  // errors, then closes)
  { cause: 'DIFF-ASYNC-ERRORS', api: '^fs(/promises)?\\.(readFile|link|utimes|lutimes|statfs)$', id: '\\((<|")', leaf: '^r\\.error\\.(message|errno|syscall|path|dest)$' },
  { cause: 'DIFF-ASYNC-ERRORS', api: '^fs\\.createReadStream$', leaf: '^r\\.end\\.error\\.(message|errno|syscall|path)$' },
  { cause: 'DIFF-SCANDIR', api: '^fs(/promises)?\\.(readdirSync|readdir|opendir)$', leaf: '^r\\.error\\.(message|syscall)$' },
  { cause: 'DIFF-ENCODINGS', api: '^fs\\.readFileSync$', id: '"ascii"', leaf: '^r(\\.\\d+)?(\\.(Buffer|length))?$' },
  { cause: 'DIFF-FD-PRIMITIVES', api: '^fs\\.(fchmod|fchmodSync|fsyncSync|ftruncateSync)$', leaf: `(${ERR}|^r\\.undefined$|^after\\.file\\.(mode|size|data)$)` },
  { cause: 'DIFF-READSYNC-RANGE', api: '^fs\\.readSync$', leaf: ERR },
  { cause: 'DIFF-REALPATH-SYSCALL', api: '^fs\\.realpathSync$', leaf: '^r\\.error\\.(message|syscall)$' },
  { cause: 'DIFF-RM', api: '^fs(/promises)?\\.(rmSync|rm)$', leaf: `(${ERR}|^r\\.undefined$|^after\\.emptydir\\.(kind|mode|mtimeMs|atimeMs)$)` },
  { cause: 'DIFF-MKDTEMP-ERROR', api: '^fs(/promises)?\\.(mkdtempSync|mkdtemp)$', leaf: '^r\\.error\\.(message|syscall|path)$' },
  { cause: 'DIFF-COPYFILE', api: '^fs/promises\\.copyFile$', leaf: ERR },
  { cause: 'DIFF-STATFS-CLASS', api: '^fs/promises\\.statfs$', leaf: '^r\\.ctor$' },
  // an argument truly MISSING: no arguments, an undefined/null/number where a path or options object
  // is required, or writeFileSync with a path and no data
  // (path left this cause at the 2.1.332 bump, 2026-11-25: modules/path.cjs checks its arguments as node does, and
  // test/node-shim-path.test.cjs holds it there; a path divergence here again is a regression, not a tolerated pair)
  { cause: 'DIFF-ARG-VALIDATION', api: '^(fs/promises\\.(unlink|readFile)|util\\.formatWithOptions)$',
    id: '\\((undefined|null|42)?[,)]', leaf: `(${ERR}|^r$)` },
  { cause: 'DIFF-ARG-VALIDATION', api: '^fs\\.writeFileSync$', id: '^fs\\.writeFileSync\\(<[^>]*>\\)$', leaf: '^r\\.error\\.(message|code)$' },
  { cause: 'DIFF-MISSING-MEMBERS', api: '^(fs\\.promises|fs/promises\\.constants|path\\.(win32|posix)|util\\.types|zlib\\.constants)$', leaf: '^r\\.(keys\\.\\w+|[A-Z][A-Z0-9_]*|undefined)$' },
  { cause: 'DIFF-STDIO-CLASS', api: '^process\\.(stdout|stderr|env)$', leaf: '^r\\.ctor$' },
  { cause: 'DIFF-ZLIB', api: '^zlib\\.inflateRawSync$', leaf: '^r\\.error\\.message$' },
  { cause: 'DIFF-OS-MEMORY-RELEASE', api: '^os\\.(totalmem|freemem|release|version)$', leaf: '^r(\\.sign)?$' },
  { cause: 'DIFF-NET-SERVER', api: '^net\\.createServer$', leaf: '^r\\.(closed|error\\.(ctor|name|message))$' },
  { cause: 'DIFF-PATH-DOTDOT', api: '^path\\.(parse|extname)$', leaf: '^r(\\.(dir|ext|name|base|root))?$' },
  { cause: 'DIFF-ISATTY-DEVNULL', api: '^tty\\.isatty$', id: '\\(0\\)$', leaf: '^r$' },
  { cause: 'DIFF-UTIL-FORMAT', api: '^util\\.(format|inspect)$', leaf: '^r$' },
  { cause: 'DIFF-STATFS-SYNC', api: '^fs\\.statfsSync$', leaf: `(${ERR}|^r\\.(typeof|ctor)$)` },
  { cause: 'DIFF-BUFFER-ENGINE-LIMITS', api: '^buffer\\.constants$', leaf: '^r\\.(MAX_LENGTH|MAX_STRING_LENGTH)$' },
];

function classify(api, id, leaf) {
  const k = CAUSES.find((c) => new RegExp(c.api).test(api) && (!c.id || new RegExp(c.id).test(id)) && new RegExp(c.leaf).test(leaf));
  return k ? k.cause : null;
}

// The listed pair for this field of this case on this platform, or null.
function knownPair(id, leaf, platform) {
  const k = KNOWN[id] && KNOWN[id][leaf];
  return k && k.on.includes(platform) ? k : null;
}

// Every pair listed for a platform: [{ id, leaf, cause }].
function pairsOn(platform) {
  const out = [];
  for (const [id, leaves] of Object.entries(KNOWN)) {
    for (const [leaf, k] of Object.entries(leaves)) if (k.on.includes(platform)) out.push({ id, leaf, cause: k.cause });
  }
  return out;
}

// A divergence line of compare.cjs (`<leaf>: node <x>, quaude <y>`) -> its leaf.
const leafOf = (line) => { const i = line.indexOf(': node '); return i < 0 ? null : line.slice(0, i); };

const causesIn = () => [...new Set(Object.values(KNOWN).flatMap((ls) => Object.values(ls).map((k) => k.cause)))];

module.exports = { BACKLOG_HEADING, CAUSES, KNOWN, classify, knownPair, pairsOn, leafOf, causesIn };
